+    display: flex;
+    gap: 1rem;
+    align-items: flex-start;
+}
+
+.kanban-column {
+    flex: 1;
+    background: #f1f3f5;
+    border-radius: 8px;
+    padding: 1rem;
+    min-width: 250px;
+}
+
+.column-header h3 {
+    margin: 0 0 1rem 0;
+    font-size: 1.1rem;
+}
+
+.column-body {
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+    min-height: 100px;
+}
+
+.task-card {
+    background: #fff;
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 0.75rem;
+}
+
+.task-title {
+    margin: 0 0 0.25rem 0;
+    font-size: 0.95rem;
+}
+
+.task-assignee {
+    margin: 0 0 0.5rem 0;
+    font-size: 0.85rem;
+    color: #6c757d;
+}
+
+.priority-badge {
+    display: inline-block;
+    padding: 0.15rem 0.5rem;
+    border-radius: 3px;
+    font-size: 0.75rem;
+    font-weight: 600;
+    text-transform: uppercase;
+    margin-right: 0.5rem;
+}
+
+.priority-high {
+    background: #f8d7da;
+    color: #842029;
+}
+
+.priority-medium {
+    background: #fff3cd;
+    color: #664d03;
+}
+
+.priority-low {
+    background: #d1e7dd;
+    color: #0f5132;
+}
+
+.task-due-date {
+    font-size: 0.8rem;
+    color: #6c757d;
+}
+
+.task-actions {
+    margin-top: 0.5rem;
+    display: flex;
+    gap: 0.5rem;
+}
+
+.btn-move {
+    padding: 0.25rem 0.5rem;
+    font-size: 0.75rem;
+    border: 1px solid #dee2e6;
+    background: #fff;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-move:hover {
+    background: #e9ecef;
+}
+
+.column-footer {
+    margin-top: 1rem;
+}
+
+.btn-add-task {
+    width: 100%;
+    padding: 0.5rem;
+    border: 1px dashed #adb5bd;
+    background: transparent;
+    border-radius: 4px;
+    cursor: pointer;
+    color: #6c757d;
+}
+
+.btn-add-task:hover {
+    background: #e9ecef;
+}
+
+.add-task-form {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+.add-task-form input,
+.add-task-form select {
+    padding: 0.4rem;
+    border: 1px solid #dee2e6;
+    border-radius: 4px;
+}
+
+.form-actions {
+    display: flex;
+    gap: 0.5rem;
+}
+
+.btn-save {
+    padding: 0.4rem 0.75rem;
+    background: #0d6efd;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-cancel {
+    padding: 0.4rem 0.75rem;
+    background: #6c757d;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.loading {
+    color: #6c757d;
+    font-style: italic;
+}
+
+.error {
+    color: #dc3545;
+    font-weight: 600;
+}
+

